package main

import "fmt"

func add(s []int) {
	s = append(s, 1)
}

func main() {
	s := make([]int, 0, 100)
	add(s)
	fmt.Println(s, len(s), cap(s))
	fmt.Println(s[:1])
}

package main

import (
	"fmt"
)

func appendLen(numbers []*int) {
	size := len(numbers)
	numbers = append(numbers, &size)
}

func main() {
	numbers := make([]*int, 0, 5)
	var number int
	for range 3 {
		number++
		numbers = append(numbers, &number)
	}

	appendLen(numbers)

	for _, number := range numbers {
		fmt.Printf("%d ", *number)
	}
}

