package main

import (
	"fmt"
	"sort"
)

func main() {
	fmt.Println(do([]int{1, 2, 3}))
}

func do(n []int) []int {
	defer func() {
		n[2] = -2
		n = append(n, 0)
		sort.Ints(n)
		n[1] = 10
	}()
	n[0] = 2
	n = append(n, 0)
	return n
}

package main

import (
	"fmt"
	"sort"
)

func main() {
	v := make([]int, 3, 5)
	fill(v)
	sr(v)
	fmt.Println(v)
}

func fill(arr []int) {
	arr[0] = 4
	arr[1] = 3
	arr[2] = 2
	arr = append(arr, 1)
	fmt.Println(arr)
}

func sr(arr []int) {
	fmt.Println(arr)
	sort.Ints(arr)
}

