package main

import "fmt"

func slices1(s []int) {
	s[1] = 20
	s = append(s, 80)
}

func slices2(s *[]int) {
	(*s)[1] = 10
	*s = append(*s, 40)
}

func main() {
	s := []int{1, 2, 3}
	slices2(&s)
	slices1(s)

	fmt.Println(s)
}
